dashboard.definition:
{
    "title": "Manage",
    "description": "Mute data during planned work, change how long an item may stay silent, keep the expected list up to date and run test blocks; every change is previewed first and recorded in the admin log.",
    "expressions": {
        "conditions": {
            "cond_ov_ready": {
                "name": "Mute form filled in",
                "value": "isSet($ov_entity$) and isSet($ov_action$) and isSet($ov_duration$) and isSet($ov_threshold$) and isSet($ov_reason$) and isSet($ov_ticket$)"
            },
            "cond_ov_done": {
                "name": "Mute form confirmed",
                "value": "isSet($ov_entity$) and isSet($ov_action$) and isSet($ov_duration$) and isSet($ov_threshold$) and isSet($ov_reason$) and isSet($ov_ticket$) and isSet($ov_confirm$)"
            },
            "cond_ex_ready": {
                "name": "Add-row form filled in",
                "value": "isSet($ex_level$) and isSet($ex_index$) and isSet($ex_host$) and isSet($ex_sourcetype$) and isSet($ex_source$) and isSet($ex_collection$) and isSet($ex_via$) and isSet($ex_profile$) and isSet($ex_interval$) and isSet($ex_crit$) and isSet($ex_owner$) and isSet($ex_site$) and isSet($ex_runbook$) and isSet($ex_description$) and isSet($ex_reason$) and isSet($ex_ticket$)"
            },
            "cond_ex_done": {
                "name": "Add-row form confirmed",
                "value": "isSet($ex_level$) and isSet($ex_index$) and isSet($ex_host$) and isSet($ex_sourcetype$) and isSet($ex_source$) and isSet($ex_collection$) and isSet($ex_via$) and isSet($ex_profile$) and isSet($ex_interval$) and isSet($ex_crit$) and isSet($ex_owner$) and isSet($ex_site$) and isSet($ex_runbook$) and isSet($ex_description$) and isSet($ex_reason$) and isSet($ex_ticket$) and isSet($ex_confirm$)"
            },
            "cond_ad_ready": {
                "name": "Adopt form filled in",
                "value": "isSet($ad_entity$) and isSet($ad_crit$) and isSet($ad_reason$) and isSet($ad_ticket$)"
            },
            "cond_ad_done": {
                "name": "Adopt form confirmed",
                "value": "isSet($ad_entity$) and isSet($ad_crit$) and isSet($ad_reason$) and isSet($ad_ticket$) and isSet($ad_confirm$)"
            },
            "cond_bk_ready": {
                "name": "Test-block form filled in",
                "value": "isSet($bk_action$) and isSet($bk_host$) and isSet($bk_level$) and isSet($bk_target$) and isSet($bk_duration$) and isSet($bk_reason$) and isSet($bk_ticket$)"
            },
            "cond_bk_done": {
                "name": "Test-block form confirmed",
                "value": "isSet($bk_action$) and isSet($bk_host$) and isSet($bk_level$) and isSet($bk_target$) and isSet($bk_duration$) and isSet($bk_reason$) and isSet($bk_ticket$) and isSet($bk_confirm$)"
            }
        }
    },
    "inputs": {
        "input_ov_host": {
            "type": "input.dropdown",
            "title": "Host",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ov_host",
                "defaultValue": "-"
            },
            "dataSources": {
                "primary": "ds_hosts"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_ov_entity": {
            "type": "input.dropdown",
            "title": "Item",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ov_entity",
                "defaultValue": "-",
                "isCascadingInput": true
            },
            "dataSources": {
                "primary": "ds_ov_entities"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_ov_action": {
            "type": "input.dropdown",
            "title": "Action",
            "options": {
                "items": [
                    {
                        "label": "Mute",
                        "value": "mute"
                    },
                    {
                        "label": "Unmute",
                        "value": "unmute"
                    },
                    {
                        "label": "Set limit",
                        "value": "threshold"
                    },
                    {
                        "label": "Clear limit",
                        "value": "clear"
                    }
                ],
                "token": "ov_action",
                "defaultValue": "mute"
            }
        },
        "input_ov_duration": {
            "type": "input.dropdown",
            "title": "Mute for",
            "options": {
                "items": [
                    {
                        "label": "1 hour",
                        "value": "3600"
                    },
                    {
                        "label": "4 hours",
                        "value": "14400"
                    },
                    {
                        "label": "1 day",
                        "value": "86400"
                    },
                    {
                        "label": "7 days",
                        "value": "604800"
                    },
                    {
                        "label": "30 days (the most allowed)",
                        "value": "2592000"
                    }
                ],
                "token": "ov_duration",
                "defaultValue": "3600"
            }
        },
        "input_ov_threshold": {
            "type": "input.text",
            "title": "New limit in seconds (Set limit only)",
            "options": {
                "token": "ov_threshold",
                "defaultValue": "-"
            }
        },
        "input_ov_reason": {
            "type": "input.text",
            "title": "Reason (required)",
            "options": {
                "token": "ov_reason",
                "placeholder": "Why? For example: patching, see CHG-123"
            }
        },
        "input_ov_ticket": {
            "type": "input.text",
            "title": "Ticket (optional, - for none)",
            "options": {
                "token": "ov_ticket",
                "defaultValue": "-"
            }
        },
        "input_ov_confirm": {
            "type": "input.dropdown",
            "title": "Confirm (writes the change)",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ov_confirm",
                "isCascadingInput": true
            },
            "dataSources": {
                "primary": "ds_ov_confirm"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            },
            "containerOptions": {
                "visibility": {
                    "showConditions": [
                        "cond_ov_ready"
                    ]
                }
            }
        },
        "input_th_text": {
            "type": "input.text",
            "title": "Search the thresholds (words separated by *)",
            "options": {
                "token": "th_text",
                "defaultValue": "*"
            }
        },
        "input_ex_level": {
            "type": "input.dropdown",
            "title": "Level",
            "options": {
                "items": [
                    {
                        "label": "Host (the host itself)",
                        "value": "host"
                    },
                    {
                        "label": "Sourcetype (one kind of data)",
                        "value": "sourcetype"
                    },
                    {
                        "label": "Source (one file or input)",
                        "value": "source"
                    }
                ],
                "token": "ex_level",
                "defaultValue": "sourcetype"
            }
        },
        "input_ex_index": {
            "type": "input.dropdown",
            "title": "Index",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ex_index",
                "defaultValue": "linux"
            },
            "dataSources": {
                "primary": "ds_indexes"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_ex_host": {
            "type": "input.text",
            "title": "Host name",
            "options": {
                "token": "ex_host",
                "placeholder": "For example pi5"
            }
        },
        "input_ex_sourcetype": {
            "type": "input.text",
            "title": "Sourcetype (not for a host row)",
            "options": {
                "token": "ex_sourcetype",
                "defaultValue": "-"
            }
        },
        "input_ex_source": {
            "type": "input.text",
            "title": "Source (source rows only)",
            "options": {
                "token": "ex_source",
                "defaultValue": "-"
            }
        },
        "input_ex_collection": {
            "type": "input.dropdown",
            "title": "Collection (how it arrives)",
            "options": {
                "items": [
                    {
                        "label": "uf (Splunk agent)",
                        "value": "uf"
                    },
                    {
                        "label": "syslog",
                        "value": "syslog"
                    },
                    {
                        "label": "hec (HTTP Event Collector)",
                        "value": "hec"
                    }
                ],
                "token": "ex_collection",
                "defaultValue": "uf"
            }
        },
        "input_ex_via": {
            "type": "input.text",
            "title": "Via relay (optional, - for none)",
            "options": {
                "token": "ex_via",
                "defaultValue": "-"
            }
        },
        "input_ex_profile": {
            "type": "input.dropdown",
            "title": "Profile",
            "options": {
                "items": [
                    {
                        "label": "heartbeat (agent heartbeat, limit 90 s)",
                        "value": "heartbeat"
                    },
                    {
                        "label": "periodic (runs every N seconds)",
                        "value": "periodic"
                    },
                    {
                        "label": "continuous (steady stream, limit 15 min)",
                        "value": "continuous"
                    },
                    {
                        "label": "sporadic (now and then, limit 24 h)",
                        "value": "sporadic"
                    },
                    {
                        "label": "info (tracked, never alerts)",
                        "value": "info"
                    }
                ],
                "token": "ex_profile",
                "defaultValue": "continuous"
            }
        },
        "input_ex_interval": {
            "type": "input.text",
            "title": "Interval in seconds (periodic only)",
            "options": {
                "token": "ex_interval",
                "defaultValue": "-"
            }
        },
        "input_ex_crit": {
            "type": "input.dropdown",
            "title": "Criticality",
            "options": {
                "items": [
                    {
                        "label": "1 (highest, alerts)",
                        "value": "1"
                    },
                    {
                        "label": "2 (alerts)",
                        "value": "2"
                    },
                    {
                        "label": "3 (no alert)",
                        "value": "3"
                    },
                    {
                        "label": "4 (lowest, no alert)",
                        "value": "4"
                    }
                ],
                "token": "ex_crit",
                "defaultValue": "2"
            }
        },
        "input_ex_owner": {
            "type": "input.text",
            "title": "Owner (optional, - for none)",
            "options": {
                "token": "ex_owner",
                "defaultValue": "-"
            }
        },
        "input_ex_site": {
            "type": "input.text",
            "title": "Site (optional, - for none)",
            "options": {
                "token": "ex_site",
                "defaultValue": "-"
            }
        },
        "input_ex_runbook": {
            "type": "input.text",
            "title": "Runbook link (optional, - for none)",
            "options": {
                "token": "ex_runbook",
                "defaultValue": "-"
            }
        },
        "input_ex_description": {
            "type": "input.text",
            "title": "Description (optional, - for none)",
            "options": {
                "token": "ex_description",
                "defaultValue": "-"
            }
        },
        "input_ex_reason": {
            "type": "input.text",
            "title": "Reason (required)",
            "options": {
                "token": "ex_reason",
                "placeholder": "Why? For example: new log file on pi5"
            }
        },
        "input_ex_ticket": {
            "type": "input.text",
            "title": "Ticket (optional, - for none)",
            "options": {
                "token": "ex_ticket",
                "defaultValue": "-"
            }
        },
        "input_ex_confirm": {
            "type": "input.dropdown",
            "title": "Confirm (writes the change)",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ex_confirm",
                "isCascadingInput": true
            },
            "dataSources": {
                "primary": "ds_ex_confirm"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            },
            "containerOptions": {
                "visibility": {
                    "showConditions": [
                        "cond_ex_ready"
                    ]
                }
            }
        },
        "input_ad_entity": {
            "type": "input.dropdown",
            "title": "Unregistered item",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ad_entity",
                "defaultValue": "-"
            },
            "dataSources": {
                "primary": "ds_ad_entities"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_ad_crit": {
            "type": "input.dropdown",
            "title": "Criticality",
            "options": {
                "items": [
                    {
                        "label": "1 (highest, alerts)",
                        "value": "1"
                    },
                    {
                        "label": "2 (alerts)",
                        "value": "2"
                    },
                    {
                        "label": "3 (no alert)",
                        "value": "3"
                    },
                    {
                        "label": "4 (lowest, no alert)",
                        "value": "4"
                    }
                ],
                "token": "ad_crit",
                "defaultValue": "2"
            }
        },
        "input_ad_reason": {
            "type": "input.text",
            "title": "Reason (required)",
            "options": {
                "token": "ad_reason",
                "placeholder": "Why? For example: pi5 now sends cron logs"
            }
        },
        "input_ad_ticket": {
            "type": "input.text",
            "title": "Ticket (optional, - for none)",
            "options": {
                "token": "ad_ticket",
                "defaultValue": "-"
            }
        },
        "input_ad_confirm": {
            "type": "input.dropdown",
            "title": "Confirm (writes the change)",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "ad_confirm",
                "isCascadingInput": true
            },
            "dataSources": {
                "primary": "ds_ad_confirm"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            },
            "containerOptions": {
                "visibility": {
                    "showConditions": [
                        "cond_ad_ready"
                    ]
                }
            }
        },
        "input_bk_action": {
            "type": "input.dropdown",
            "title": "Action",
            "options": {
                "items": [
                    {
                        "label": "Add a test block",
                        "value": "add"
                    },
                    {
                        "label": "Remove a test block",
                        "value": "remove"
                    }
                ],
                "token": "bk_action",
                "defaultValue": "add"
            }
        },
        "input_bk_host": {
            "type": "input.dropdown",
            "title": "Host",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "bk_host",
                "defaultValue": "-"
            },
            "dataSources": {
                "primary": "ds_hosts"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_bk_level": {
            "type": "input.dropdown",
            "title": "Block level",
            "options": {
                "items": [
                    {
                        "label": "Whole host (all its data)",
                        "value": "host"
                    },
                    {
                        "label": "One sourcetype",
                        "value": "sourcetype"
                    },
                    {
                        "label": "One exact raw source",
                        "value": "source"
                    }
                ],
                "token": "bk_level",
                "defaultValue": "host"
            }
        },
        "input_bk_target": {
            "type": "input.dropdown",
            "title": "Sourcetype or raw source",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "bk_target",
                "defaultValue": "-",
                "isCascadingInput": true
            },
            "dataSources": {
                "primary": "ds_bk_targets"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_bk_duration": {
            "type": "input.dropdown",
            "title": "Block for",
            "options": {
                "items": [
                    {
                        "label": "5 minutes",
                        "value": "300"
                    },
                    {
                        "label": "15 minutes",
                        "value": "900"
                    },
                    {
                        "label": "1 hour",
                        "value": "3600"
                    },
                    {
                        "label": "4 hours",
                        "value": "14400"
                    },
                    {
                        "label": "24 hours (the most allowed)",
                        "value": "86400"
                    }
                ],
                "token": "bk_duration",
                "defaultValue": "900"
            }
        },
        "input_bk_reason": {
            "type": "input.text",
            "title": "Reason (required)",
            "options": {
                "token": "bk_reason",
                "placeholder": "Why? For example: test that the app sees pi5 go missing"
            }
        },
        "input_bk_ticket": {
            "type": "input.text",
            "title": "Ticket (optional, - for none)",
            "options": {
                "token": "bk_ticket",
                "defaultValue": "-"
            }
        },
        "input_bk_confirm": {
            "type": "input.dropdown",
            "title": "Confirm (writes the change)",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "bk_confirm",
                "isCascadingInput": true
            },
            "dataSources": {
                "primary": "ds_bk_confirm"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            },
            "containerOptions": {
                "visibility": {
                    "showConditions": [
                        "cond_bk_ready"
                    ]
                }
            }
        },
        "input_lg_text": {
            "type": "input.text",
            "title": "Search the log (words separated by *)",
            "options": {
                "token": "lg_text",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-24h",
                        "latest": "now"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_hosts": {
            "type": "ds.search",
            "name": "Hosts",
            "options": {
                "query": "| `dh_ui_status(dh_status)` | stats count by host | eval label=host, value=host | table label value | appendpipe [| stats count | eval label=\"Choose a host\", value=\"-\" | table label value] | eval dh_o=if(value==\"-\", 0, 1) | sort 0 dh_o | table label value"
            }
        },
        "ds_ov_entities": {
            "type": "ds.search",
            "name": "Items of the host",
            "options": {
                "query": "| `dh_ui_status(dh_status)` | where host==$ov_host|s$ | eval dh_lv=case(level==\"host\", 0, level==\"sourcetype\", 1, true(), 2), label=`dh_ui_item_words(entity_id)`.\" (\".status.\")\", value=entity_id | sort 0 dh_lv entity_id | table label value | appendpipe [| stats count | eval label=if($ov_host|s$==\"-\", \"Choose a host first\", \"Choose an item\"), value=\"-\" | table label value] | eval dh_o=if(value==\"-\", 0, 1) | sort 0 dh_o | table label value"
            }
        },
        "ds_ov_plan": {
            "type": "ds.search",
            "name": "Mute or limit: plan",
            "options": {
                "query": "| makeresults | eval entity_id=$ov_entity|s$, dh_action=$ov_action|s$, dh_secs=if($ov_action|s$==\"mute\", $ov_duration|s$, $ov_threshold|s$), reason=$ov_reason|s$, ticket=$ov_ticket|s$ | `dh_ui_actor` | `dh_ui_override_plan(dh_overrides, dh_admin_log, now())`"
            }
        },
        "ds_ov_preview": {
            "type": "ds.chain",
            "name": "Mute or limit: preview",
            "options": {
                "extend": "ds_ov_plan",
                "query": "| table ui_change ui_item ui_now ui_after check | `dh_ui_headers`"
            }
        },
        "ds_ov_confirm": {
            "type": "ds.chain",
            "name": "Mute or limit: confirmation choice",
            "options": {
                "extend": "ds_ov_plan",
                "query": "| where dh_ok==1 | eval label=dh_label, value=dh_token | table label value"
            }
        },
        "ds_ov_apply": {
            "type": "ds.search",
            "name": "Mute or limit: apply",
            "options": {
                "query": "| makeresults | eval entity_id=$ov_entity|s$, dh_action=$ov_action|s$, dh_secs=if($ov_action|s$==\"mute\", $ov_duration|s$, $ov_threshold|s$), reason=$ov_reason|s$, ticket=$ov_ticket|s$ | `dh_ui_actor` | `dh_ui_override_plan(dh_overrides, dh_admin_log, now())` | eval dh_confirm=$ov_confirm|s$ | `dh_ui_override_write(dh_overrides, dh_admin_log, now())` | `dh_ui_headers`"
            }
        },
        "ds_overrides": {
            "type": "ds.search",
            "name": "Current mutes and limit overrides",
            "options": {
                "query": "| `dh_ui_overrides(dh_overrides)` | `dh_ui_headers`"
            }
        },
        "ds_thresholds": {
            "type": "ds.search",
            "name": "Thresholds",
            "options": {
                "query": "| `dh_ui_status(dh_status)` | eval f_site=\"*\", f_owner=\"*\", f_index=\"*\", f_crit=\"*\", f_status=\"*\", f_text=$th_text|s$ | `dh_ui_filter` | `dh_ui_thresholds(dh_baseline, dh_expected)` | `dh_ui_headers`"
            }
        },
        "ds_indexes": {
            "type": "ds.search",
            "name": "Indexes the app watches",
            "options": {
                "query": "| `dh_ui_indexes` | appendpipe [| stats count | eval label=\"None (host row)\", value=\"-\" | table label value]"
            }
        },
        "ds_ex_plan": {
            "type": "ds.search",
            "name": "Add an expected row: plan",
            "options": {
                "query": "| makeresults | eval dh_action=\"add\", level=$ex_level|s$, index=$ex_index|s$, host=$ex_host|s$, sourcetype=$ex_sourcetype|s$, source=$ex_source|s$, collection=$ex_collection|s$, via=$ex_via|s$, profile=$ex_profile|s$, interval_secs=$ex_interval|s$, criticality=$ex_crit|s$, owner=$ex_owner|s$, site=$ex_site|s$, runbook=$ex_runbook|s$, description=$ex_description|s$, reason=$ex_reason|s$, ticket=$ex_ticket|s$ | `dh_ui_actor` | `dh_ui_expected_plan(dh_expected, dh_admin_log, now())`"
            }
        },
        "ds_ex_preview": {
            "type": "ds.chain",
            "name": "Add an expected row: preview",
            "options": {
                "extend": "ds_ex_plan",
                "query": "| table ui_change ui_item ui_now ui_after check | `dh_ui_headers`"
            }
        },
        "ds_ex_confirm": {
            "type": "ds.chain",
            "name": "Add an expected row: confirmation choice",
            "options": {
                "extend": "ds_ex_plan",
                "query": "| where dh_ok==1 | eval label=dh_label, value=dh_token | table label value"
            }
        },
        "ds_ex_apply": {
            "type": "ds.search",
            "name": "Add an expected row: apply",
            "options": {
                "query": "| makeresults | eval dh_action=\"add\", level=$ex_level|s$, index=$ex_index|s$, host=$ex_host|s$, sourcetype=$ex_sourcetype|s$, source=$ex_source|s$, collection=$ex_collection|s$, via=$ex_via|s$, profile=$ex_profile|s$, interval_secs=$ex_interval|s$, criticality=$ex_crit|s$, owner=$ex_owner|s$, site=$ex_site|s$, runbook=$ex_runbook|s$, description=$ex_description|s$, reason=$ex_reason|s$, ticket=$ex_ticket|s$ | `dh_ui_actor` | `dh_ui_expected_plan(dh_expected, dh_admin_log, now())` | eval dh_confirm=$ex_confirm|s$ | `dh_ui_expected_write(dh_expected, dh_admin_log, now())` | `dh_ui_headers`"
            }
        },
        "ds_unreg": {
            "type": "ds.search",
            "name": "Unregistered",
            "options": {
                "query": "| `dh_ui_unregistered(dh_expected, dh_state_fast, dh_state_slow, dh_baseline, now())`"
            }
        },
        "ds_unreg_view": {
            "type": "ds.chain",
            "name": "Unregistered (shown)",
            "options": {
                "extend": "ds_unreg",
                "query": "| eval ui_item=`dh_ui_item_words(entity_id)` | table ui_item level index host sourcetype sources last_seen first_seen suggested_profile days entity_id | `dh_ui_headers`"
            }
        },
        "ds_ad_entities": {
            "type": "ds.chain",
            "name": "Unregistered choices",
            "options": {
                "extend": "ds_unreg",
                "query": "| eval label=`dh_ui_item_words(entity_id)`.\", last seen \".last_seen, value=entity_id | table label value | appendpipe [| stats count | eval label=\"Choose an unregistered item\", value=\"-\" | table label value] | eval dh_o=if(value==\"-\", 0, 1) | sort 0 dh_o | table label value"
            }
        },
        "ds_ad_plan": {
            "type": "ds.search",
            "name": "Adopt: plan",
            "options": {
                "query": "| makeresults | eval entity_id=$ad_entity|s$ | `dh_ui_adopt_row(dh_baseline, dh_fwd)` | eval criticality=$ad_crit|s$, reason=$ad_reason|s$, ticket=$ad_ticket|s$ | `dh_ui_actor` | `dh_ui_expected_plan(dh_expected, dh_admin_log, now())`"
            }
        },
        "ds_ad_preview": {
            "type": "ds.chain",
            "name": "Adopt: preview",
            "options": {
                "extend": "ds_ad_plan",
                "query": "| table ui_change ui_item ui_now ui_after check | `dh_ui_headers`"
            }
        },
        "ds_ad_confirm": {
            "type": "ds.chain",
            "name": "Adopt: confirmation choice",
            "options": {
                "extend": "ds_ad_plan",
                "query": "| where dh_ok==1 | eval label=dh_label, value=dh_token | table label value"
            }
        },
        "ds_ad_apply": {
            "type": "ds.search",
            "name": "Adopt: apply",
            "options": {
                "query": "| makeresults | eval entity_id=$ad_entity|s$ | `dh_ui_adopt_row(dh_baseline, dh_fwd)` | eval criticality=$ad_crit|s$, reason=$ad_reason|s$, ticket=$ad_ticket|s$ | `dh_ui_actor` | `dh_ui_expected_plan(dh_expected, dh_admin_log, now())` | eval dh_confirm=$ad_confirm|s$ | `dh_ui_expected_write(dh_expected, dh_admin_log, now())` | `dh_ui_headers`"
            }
        },
        "ds_bk_sources": {
            "type": "ds.search",
            "name": "Raw sources of the host (24 h)",
            "options": {
                "query": "| tstats count as events max(_indextime) as it where index IN (linux, windows, network) [| makeresults | eval host=$bk_host|s$ | `dh_ui_host_terms`] earliest=-24h latest=+1d by index sourcetype source | eval source_norm=`dh_source_norm(source)`, last_seen=strftime(it, `dh_ui_time_fmt_tz`) | sort 0 sourcetype source | table index sourcetype source source_norm events last_seen"
            }
        },
        "ds_bk_sources_view": {
            "type": "ds.chain",
            "name": "Raw sources of the host (24 h) (shown)",
            "options": {
                "extend": "ds_bk_sources",
                "query": "| `dh_ui_headers`"
            }
        },
        "ds_bk_targets": {
            "type": "ds.chain",
            "name": "Block target choices",
            "options": {
                "extend": "ds_bk_sources",
                "query": "| eval lvl=$bk_level|s$ | where lvl!=\"host\" | eval value=if(lvl==\"source\", sourcetype.\"|\".source, sourcetype.\"|*\"), label=if(lvl==\"source\", sourcetype.\" › \".source.\" (exact raw name; normalized: \".source_norm.\")\", sourcetype) | stats count by label value | table label value | appendpipe [| stats count | eval label=case($bk_level|s$==\"host\", \"Not needed for a whole-host block\", $bk_level|s$==\"source\", \"Choose the raw source\", true(), \"Choose the sourcetype\"), value=\"-\" | table label value] | eval dh_o=if(value==\"-\", 0, 1) | sort 0 dh_o | table label value"
            }
        },
        "ds_bk_plan": {
            "type": "ds.search",
            "name": "Test block: plan",
            "options": {
                "query": "| makeresults | eval dh_action=$bk_action|s$, level=$bk_level|s$, host=$bk_host|s$, target=$bk_target|s$, dh_secs=$bk_duration|s$, reason=$bk_reason|s$, ticket=$bk_ticket|s$ | `dh_ui_actor` | `dh_ui_block_plan(hl_ingest_block, dh_admin_log, now())`"
            }
        },
        "ds_bk_preview": {
            "type": "ds.chain",
            "name": "Test block: preview",
            "options": {
                "extend": "ds_bk_plan",
                "query": "| table ui_change ui_item ui_now ui_after check source_norm | `dh_ui_headers`"
            }
        },
        "ds_bk_confirm": {
            "type": "ds.chain",
            "name": "Test block: confirmation choice",
            "options": {
                "extend": "ds_bk_plan",
                "query": "| where dh_ok==1 | eval label=dh_label, value=dh_token | table label value"
            }
        },
        "ds_bk_apply": {
            "type": "ds.search",
            "name": "Test block: apply",
            "options": {
                "query": "| makeresults | eval dh_action=$bk_action|s$, level=$bk_level|s$, host=$bk_host|s$, target=$bk_target|s$, dh_secs=$bk_duration|s$, reason=$bk_reason|s$, ticket=$bk_ticket|s$ | `dh_ui_actor` | `dh_ui_block_plan(hl_ingest_block, dh_admin_log, now())` | eval dh_confirm=$bk_confirm|s$ | `dh_ui_block_write(hl_ingest_block, dh_admin_log, now())` | `dh_ui_headers`"
            }
        },
        "ds_blocks": {
            "type": "ds.search",
            "name": "Current test blocks",
            "options": {
                "query": "| `dh_ui_blocks(hl_ingest_block, now())` | `dh_ui_headers`"
            }
        },
        "ds_log": {
            "type": "ds.search",
            "name": "Admin log",
            "options": {
                "query": "| `dh_ui_admin_log(dh_admin_log)` | eval f_text=$lg_text|s$ | `dh_ui_hay_filter` | head 1000 | `dh_ui_headers`"
            }
        }
    },
    "visualizations": {
        "viz_mute_intro": {
            "type": "splunk.markdown",
            "options": {
                "markdown": "**Mute** an item during planned work, so it does not alert, or change how long it may stay silent before it counts as late (its **limit**). Fill in the form; the preview shows the change; nothing is written until you choose **Apply** under **Confirm**. Analysts may mute; every change is recorded on the Admin log tab. Times are in your Splunk time zone."
            }
        },
        "viz_ov_steps": {
            "type": "splunk.markdown",
            "options": {
                "markdown": "**Preview: fill in the form above.** Choose the **Host**, then the **Item** (the host's own row, *whole host*, mutes everything it sends). Choose the **Action**, how long, and write a **Reason**. The preview of the change then appears here."
